public class Solution {
    public static long largestRectangle(int[] heights) {
        int n = heights.length;
        long best = 0;
        for (int i = 0; i < n; i++) {
            int left = i;
            while (left - 1 >= 0 && heights[left - 1] >= heights[i]) left--;
            int right = i;
            while (right + 1 < n && heights[right + 1] >= heights[i]) right++;
            long width = right - left + 1;
            best = Math.max(best, (long) heights[i] * width);
        }
        return best;
    }

    public static void main(String[] args) {
        System.out.println(largestRectangle(new int[]{2, 1, 5, 6, 2, 3}));
    }
}

